export const CAMPUS_ENGINE_CSS = "/* Squirrel Social — IISER Kolkata map page. Inlined by scripts/world-engine.mjs. Animations are\n   transform / opacity only (GPU); the page sits on the same near-black as the map. */\nhtml, body { margin: 0; height: 100%; background: #050608; overflow: hidden; -webkit-tap-highlight-color: transparent; -webkit-user-select: none; user-select: none; }\n#map { position: absolute; inset: 0; }\n.maplibregl-canvas { outline: none; }\n#vignette { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(130% 95% at 50% 48%, rgba(0,0,0,0) 58%, rgba(0,0,0,0.5) 100%); }\n\n.maplibregl-ctrl-top-right { top: var(--inset-top, 0px); right: var(--inset-right, 0px); }\n.maplibregl-ctrl-attrib { background: rgba(5,6,8,0.6) !important; color: #6E7280; font: 10px/1.4 -apple-system, system-ui, sans-serif; }\n.maplibregl-ctrl-attrib a { color: #8A8F9C; }\n.maplibregl-ctrl-attrib-button { filter: invert(1) opacity(0.5); background-color: transparent !important; }\n\n#tip { position: absolute; left: 0; top: 0; pointer-events: none; opacity: 0; transition: opacity 120ms ease; z-index: 3;\n  background: rgba(8,9,12,0.94); border: 1px solid rgba(236,232,222,0.14); border-left: 2px solid #D7FF1F; padding: 7px 10px 7px 9px;\n  font: 600 11px/1.35 -apple-system, system-ui, sans-serif; letter-spacing: 0.08em; color: #ECE8DE; display: flex; flex-direction: column; gap: 2px; white-space: nowrap; }\n#tip b { font-weight: 800; letter-spacing: 0.12em; text-transform: uppercase; }\n#tip span { font-size: 10px; }\n\n/* YOU: the squirrel mark on a dark core, a slow pulse, a heading wedge. */\n.me { position: relative; width: 48px; height: 48px; pointer-events: none; color: #D7FF1F; }\n.me > * { position: absolute; left: 50%; top: 50%; }\n.me-pulse { width: 48px; height: 48px; margin: -24px 0 0 -24px; border-radius: 50%; border: 1.5px solid rgba(215,255,31,0.5); animation: me-pulse 2.6s cubic-bezier(.2,.6,.3,1) infinite; }\n.me-core { width: 28px; height: 28px; margin: -14px 0 0 -14px; border-radius: 50%; background: #07080B; border: 1.5px solid #D7FF1F;\n  box-shadow: 0 0 0 3px rgba(5,6,8,0.85), 0 0 16px rgba(215,255,31,0.35); display: flex; align-items: center; justify-content: center; }\n.me-core svg { width: 19px; height: 19px; display: block; }\n.me-dir { width: 0; height: 0; margin: -27px 0 0 -6px; border-left: 6px solid transparent; border-right: 6px solid transparent; border-bottom: 10px solid #D7FF1F; transform-origin: 6px 27px; opacity: 0; transition: transform 300ms ease, opacity 200ms; }\n.me-tag { display: none; margin: 18px 0 0 0; transform: translateX(-50%); white-space: nowrap; font: 800 8.5px/1 -apple-system, system-ui, sans-serif; letter-spacing: 0.2em; color: #D7FF1F; background: rgba(5,6,8,0.9); border: 1px dashed rgba(215,255,31,0.6); padding: 3px 5px 2px; }\n.me-preview .me-core { border-style: dashed; }\n.me-preview .me-tag { display: block; }\n@keyframes me-pulse { 0% { transform: scale(0.5); opacity: 0.9; } 100% { transform: scale(1.6); opacity: 0; } }\n\n#fallback { position: absolute; inset: 0; display: none; align-items: center; justify-content: center; color: #6E7280; font: 600 12px -apple-system, system-ui, sans-serif; letter-spacing: 0.2em; }\n@media (prefers-reduced-motion: reduce) { .me-pulse { animation: none; } }\n";
